head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onbodymouseout]<br/>Body, Footer Cell 영역에서 마우스 포인터가 나갔을때 발생합니다.",
    "validation" : [
        "Header, Footer 영역 내에서 마우스 포인터가 다른 Header, Footer Cell 로 넘어간 경우도 발생합니다.",
        "RowNum, RowStauts Column 과 Footer 영역의 Cell 에서도 이벤트가 발생합니다.",
        "RowNum, RowStatus Column 과 Footer 영역의 Cell 인 경우 빈 객체가 전달됩니다.",
        "Body Cell 내에서 내부 요소 영역에서 마우스 포인터가 나갈때도 onbodymouseout 이벤트가 발생합니다.",
        "Body, Footer Cell 에서 GridView 영역 밖에서 마우스가 나가면 onbodymouseout > ongridmouseleave 순서로 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - rowNumVisible / rowStatusVisible = true (RowNum / RowStatus Column 셀 검증용)
//  - Footer(footer Table) 포함 (Footer Cell 검증용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="RowNum/RowStatus Column + Footer 포함 그리드 / Body 셀은 info 인덱스, RowNum/RowStatus/Footer 셀은 빈 객체 / 그리드 밖으로 나가면 onbodymouseout > ongridmouseleave 순서 (결과창 라인 순서)"', '', 'label1');

    // target 생성 (이벤트 바인딩은 createEList 공통 함수 사용)
    let eList = $c.gcm.createEList(["onbodymouseout", "ongridmouseleave"]);

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" autoFit="allColumn" rowNumVisible="true" rowStatusVisible="true" rowNumHeaderValue="No." rowStatusHeaderValue="St." ' + eList + ' checkAllType="false" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="onbodymouseout 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="ft1" value="Footer1"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="ft2" value="Footer2"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="ft3" value="Footer3"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="ft4" value="Footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        'target1',
        "gridView",
        strTarget,
        grp_comp
    );
}



// Body, Footer Cell 영역에서 마우스가 나갈 때 발생
//  - 발생 즉시 한 줄(▶) 출력 → 결과창 라인 순서 = 실제 이벤트 발생 순서
//  - info 는 커스텀 객체이므로 속성 개별 출력
//    · Body 일반 셀  : info.rowIndex / info.colIndex 인덱스값
//    · RowNum/RowStatus/Footer 셀 : 빈 객체 ({} → 속성 undefined)
scwin.target1_onbodymouseout = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onbodymouseout");
    let isEmpty = (info.rowIndex === undefined && info.colIndex === undefined);
    if (isEmpty) {
        wf_body_bottom.getObj("scwin").setReturnValue("info : {} (빈 객체)");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("info.rowIndex : " + info.rowIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("info.colIndex : " + info.colIndex);
    }
}



// GridView 영역 밖으로 마우스가 나갈 때 발생 (발생 순서 관찰용)
//  - 발생 즉시 한 줄(▶) 출력
scwin.target1_ongridmouseleave = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ ongridmouseleave");
}
